<script setup lang="ts">
/**
 * An Input preset for passwords, with a reveal toggle (`design/components/password-input.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/password-input.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { computed, onBeforeUnmount, onMounted, ref, useTemplateRef, watch } from 'vue'

import { Icon, agentMember } from '@polymorph/vue'
import styles from '@polymorph/recipes/controls/password-input.module.css'
import Input from './Input.vue'

export interface PasswordInputProps {
  ariaDescribedby?: string
  /**
   * Wired by FormField; set directly only when there is no visible label.
   */
  ariaLabel?: string
  ariaLabelledby?: string
  ariaRequired?: boolean
  /**
   * Has a default, unlike Input's plain passthrough, because a password field without one breaks
   * password managers and WCAG 1.3.5. Sign-up flows pass `'new-password'`. Other values belong
   * to other members (one-time codes use OTPInput).
   */
  autoComplete?: 'current-password' | 'new-password'
  defaultValue?: string
  disabled?: boolean
  id?: string
  invalid?: boolean
  name?: string
  placeholder?: string
  readOnly?: boolean
  size?: 'sm' | 'md' | 'lg'
  /**
   * The toggle's accessible name ("Show password"). The member has no built-in text.
   */
  toggleLabel: string
  value?: string
}

defineOptions({ name: 'PasswordInput', inheritAttrs: false })

const props = withDefaults(defineProps<PasswordInputProps>(), {
  ariaRequired: undefined,
  autoComplete: 'current-password',
  disabled: false,
  invalid: false,
  readOnly: false,
  size: 'md',
})
const emit = defineEmits<{ change: [value: string, event: Event] }>()
const revealed = ref(false)
const held = ref({
  start: null as number | null,
  end: null as number | null,
  direction: 'none' as 'forward' | 'backward' | 'none',
})
const frame = useTemplateRef<HTMLElement>('frame')
const field = computed(() => frame.value?.querySelector('input') ?? null)
const effect1 = () => {
  ;(field.value?.setAttribute('spellcheck', 'false'),
    field.value?.setAttribute('autocapitalize', 'off'),
    field.value?.setAttribute('autocorrect', 'off'))
}
onMounted(effect1)
const effect2 = () => {
  held.value.start !== null &&
    held.value.end !== null &&
    (field.value?.setSelectionRange(held.value.start, held.value.end, held.value.direction),
    requestAnimationFrame(() =>
      field.value?.setSelectionRange(held.value.start, held.value.end, held.value.direction),
    ))
}
watch(() => revealed.value, effect2, { flush: 'post' })
let release3: (() => void) | undefined
const effect3 = () => {
  release3?.()
  const ran = agentMember({
    member: 'PasswordInput',
    element: () => frame.value?.querySelector('input'),
    state: () => ({
      value: frame.value?.querySelector('input')?.value ?? '',
      revealed: revealed.value,
      disabled: props.disabled,
      invalid: props.invalid,
      readonly: props.readOnly,
    }),
    actions: {},
    secret: ['value'],
  })
  release3 = () => {
    ran()
  }
}
onMounted(effect3)
onBeforeUnmount(() => release3?.())
</script>

<template>
  <span
    ref="frame"
    :class="styles.password"
    :data-size="size"
    :data-disabled="disabled ? '' : undefined"
    :data-invalid="invalid ? '' : undefined"
    :data-readonly="readOnly ? '' : undefined"
    :data-state="revealed ? 'visible' : 'hidden'"
    data-member="password-input"
  >
    <Input
      :type="revealed ? 'text' : 'password'"
      :value="value"
      :defaultValue="defaultValue"
      :placeholder="placeholder"
      :size="size"
      :disabled="disabled"
      :readOnly="readOnly"
      :invalid="invalid"
      :autoComplete="autoComplete"
      :name="name"
      :id="id"
      :aria-label="ariaLabel"
      :aria-labelledby="ariaLabelledby"
      :aria-describedby="ariaDescribedby"
      :aria-required="ariaRequired"
      @change="(next, event) => emit('change', next, event)"
    >
      <template #trailing>
        <!-- toggle -->
        <button
          :class="styles.toggle"
          type="button"
          :disabled="disabled"
          :aria-pressed="revealed"
          :aria-label="toggleLabel"
          @click="
            ((held = {
              start: field?.selectionStart ?? null,
              end: field?.selectionEnd ?? null,
              direction: field?.selectionDirection ?? 'none',
            }),
            (revealed = !revealed))
          "
        >
          <Icon v-if="revealed" name="hidden" :size="size" />
          <Icon v-else name="visible" :size="size" />
        </button>
      </template>
    </Input>
  </span>
</template>
